WITH parsed AS (SELECT id, service, log_ts, payload_json, context, context['version'] AS version, GET_JSON_OBJECT(payload_json, '$.duration') AS duration_text, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').user.tier AS tier FROM app_logs WHERE HOUR(log_ts) BETWEEN 11 AND 16) SELECT id, service, log_ts, duration_text, tier, ROW_NUMBER() OVER (PARTITION BY tier, service ORDER BY log_ts DESC, id) AS seq_no, FIRST_VALUE(tier, TRUE) OVER (PARTITION BY tier, service ORDER BY log_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_tier FROM parsed;
